-- Solar Phase 4E: locked curated 42 natural objects + 5 historical spacecraft.
-- State binaries remain governed external assets; PostgreSQL stores the authority ledger.

ALTER TABLE loom_solar.ephemeris_source DROP CONSTRAINT ephemeris_source_state_capability_check;
ALTER TABLE loom_solar.ephemeris_source ADD CONSTRAINT ephemeris_source_state_capability_check CHECK (state_capability IN ('DIRECT_SPICE_2250_QUALIFIED','DIRECT_SPICE_PARTIAL_2135','DIRECT_SPICE_PARTIAL_2226','DIRECT_SPICE_PARTIAL_2200','DIRECT_SPICE_PARTIAL_2199','EMPIRICAL_PROPAGATED_2250','HORIZONS_SPK_2250_QUALIFIED','EPHEMERIS_PARTIAL','CATALOG_ONLY','UNRESOLVED'));

UPDATE loom_solar.body SET parent_body_id=v.parent_id FROM (VALUES
('NIX','PLUTO'),
('HYDRA','PLUTO'),
('KERBEROS','PLUTO'),
('STYX','PLUTO'),
('NEREID','NEPTUNE_SYSTEM_BARYCENTER'),
('PROTEUS','NEPTUNE_SYSTEM_BARYCENTER'),
('DACTYL','IDA'),
('SELAM','DINKINESH')) AS v(body_id,parent_id) WHERE loom_solar.body.body_id=v.body_id;
CREATE TABLE loom_solar.curated_cohort_member (body_id text PRIMARY KEY REFERENCES loom_solar.body(body_id), cohort text NOT NULL CHECK (cohort IN ('NATURAL','SPACECRAFT')), supplied_entry integer NOT NULL UNIQUE, supplied_name text NOT NULL, final_outcome text NOT NULL CHECK (final_outcome IN ('QUALIFIED_DIRECT','QUALIFIED_HORIZONS','QUALIFIED_PROPAGATED','PARTIAL','CATALOG_ONLY','UNRESOLVED')), reason text NOT NULL);
CREATE TABLE loom_solar.object_metadata (body_id text PRIMARY KEY REFERENCES loom_solar.body(body_id), object_kind text NOT NULL, mission_id text, launch_epoch timestamptz, lifecycle_status text, navigation_semantics text, notes text);
DO $$ DECLARE b integer; i integer; c integer; BEGIN SELECT count(*) INTO b FROM loom_solar.body WHERE status='ACTIVE'; SELECT count(*) INTO i FROM loom_solar.body_identifier WHERE status='ACTIVE'; SELECT count(*) INTO c FROM loom_solar.curated_cohort_member; IF b<>110 OR i<>110 OR c<>47 THEN RAISE EXCEPTION 'Phase-4E expected 110 bodies/110 identifiers/47 cohort rows, got %/%/%',b,i,c; END IF; END $$;
